 return <>{grouped&&<tr className={"'`group-row group-${statusClass(group.status as Status)}`}><td colSpan={visibleColumns.length+2}><button onClick={()=>setClosedGroups(prev=>{const s=new Set(prev);s.has(group.status)?s.delete(group.status):s.add(group.status);return s})} aria-expanded={!closedGroups.has(group.status)}><Icon name="chevron" size={12} className={closedGroups.has(group.status)?'"'':'down'}/><span className={"'`group-status-dot ${statusClass(group.status as Status)}`}/><strong>{group.status}</strong><span className="group-count">{group.rows.length}</span><span className="group-total">{money(group.rows.reduce((s,o)=>s+o.amount,0))}</span></button></td></tr>}{!closedGroups.has(group.status)&&group.rows.map(o=><tr key={o.id} className={selected.has(o.id)?'"'selected-row':''}><td className=\"checkbox-cell\"><input aria-label={"'`Выбрать заказ ${o.id}`} type="checkbox" checked={selected.has(o.id)} onChange={()=>toggleSelected(o.id)}/></td>{visibleColumns.map(c=><td key={c} className={`column-${c}`}>{renderCell(o,c)}</td>)}<td className="row-action-cell"><button className="icon-button" title={`Открыть заказ ${o.id}`} onClick={()=>openDetail(o)}><Icon name="more" size={17}/></button></td></tr>)}</>
